// App identity + version, shown in Settings (About area) next to the
// Check for Update button.
//
// Versioning (Anthony's rule, Nov 2, 2026): semantic versions —
// bump PATCH for bug fixes (1.0.0 -> 1.0.1), MINOR for new features
// or additions (1.0.0 -> 1.1.0), MAJOR only for a big release
// (1.0.0 -> 2.0.0). Every future build/edit increments the version
// accordingly so anyone running the app can tell exactly which
// version they have when they check for updates. This build starts
// the numbering at 1.0.0.
//
// BUILD_MARKER is the single source of truth for the version: the
// marker string is embedded verbatim in the app's JS bundle, and
// Check for Update fetches the page the server is currently serving
// (following its script reference to the current bundle) and
// compares the marker it finds against the one baked into the
// running copy. A newer marker means a newer build has been
// published — that's how fixes reach Anthony and, later, his
// friends, with no reinstall. Reload to update first re-fetches
// the page and bundle with cache: "reload" so the phone's cached
// copies are replaced with the fresh build, THEN reloads: a plain
// reload alone was served from the webview's cache and kept
// landing back on the old version (Anthony's bug, Nov 2, 2026).
export const BUILD_MARKER = "mycollectibles-build-v1.82.3";
export const APP_VERSION = BUILD_MARKER.replace(
  "mycollectibles-build-v",
  "",
);
// The app's official name (Anthony, Nov 2, 2026): Vault X — renamed
// from My Collectibles (and briefly Shadow Vault) the same day.
export const APP_NAME = "Vault X";

// Per-version changelog (Anthony's request, Nov 2, 2026): when Check
// for Update finds a newer version, the update prompt shows these
// notes so the user knows exactly what is changing before they
// reload. Voice: clear and simple — short plain bullets anyone can
// understand at a glance, with a little light tech talk only where
// it genuinely helps (naming a feature or the server is fine).
// Every version bump ships with its entry here.
//
// The notes are written as one inline JSON literal on purpose: the
// JSON text lands verbatim in the built bundle, so an OLDER running
// copy can read a NEWER build's notes straight out of the newer
// bundle during Check for Update (see changelogInBundle in App.tsx).
// Keep bullets free of curly-brace and backslash characters, which
// would break that read.
export const CHANGELOG_EMBED =
  "mc-changelog:" +
  `{"1.82.3": ["Removed the buy handoffs: the missing-cards sheet and the deck collection check no longer send your lists out to have a TCGplayer cart built for you. Nothing leaves the app. Every missing card still carries its own TCGplayer link — tap it to open that card on TCGplayer and shop there yourself, exactly as before."], "1.82.2": ["Epic cards fixed: an Epic has exactly ONE finish, and its line is labeled Epic. The card page for an Epic (like Tiana 220 from Hyperia City) used to offer Regular and Cold Foil steppers — both wrong, since Epics are foil-only. Now there is a single Epic stepper. Enchanted and Iconic printings, which are foil-only too, likewise show their single finish line only."], "1.82.1": ["Lorcana chapter tiles: every chapter tile now carries the purple border — before, only the selected chapter (Chapter One) had it, and it is a good look. The selected chapter still stands out with its extra ring.", "Library shelf, finished: Quest books now follow the same owned-only rule as chapters and promos — a Quest binder appears only when you own at least one card from it, so Quest 3 no longer shows on a shelf when nothing from it is owned.", "Back-button fix: a binder opened from the Library (promo, chapter, Quest, or the comics binder) now takes its own step in the back stack, so one press of the phone Back button closes the binder and lands you back on the Library — never straight out of the app. Three Backs still exit from anywhere, as before.", "Comics slabs: the grade — the 9.8 — now sits in the middle of the slab label instead of off to the side."], "1.82.0": ["The Marketplace is LIVE: the Coming Soon overlay is off and the Marketplace tab in Social opens the real thing — browse listings, visit a seller shop, list your own items, and Buy Now, all feeding into the same in-person confirmation and Trust as trades.", "Bug reports can now carry a screenshot: attach a photo from your phone in the Bug form and it travels with the ticket, so it sits right alongside your report. Circle the spot in your phone photo editor first — a note under the form reminds you; there are no drawing tools in the app.", "Share a deck by mail: open one of your decks in My Decks, tap Share this deck by mail, pick a connected collector, and the full deck list lands in their Inbox as plain text — deck name, inks, and every card with its quantity, number, and set.", "The Friends area on Social is trimmed down to just your friends and adding a friend — the Trust Score line and the other extra info blocks are out of that spot. Your Trust Score still lives on your profile and Collector ID as before.", "Letter avatars now look the same everywhere: the glowing-ring circle from Best Matches is the standard across the app — Friends, profiles, Forums, Marketplace, and Admin all render the same avatar."], "1.81.0": ["The Funko tile on Your Collections now shows the Crown artwork — the minimal glowing crown over the figure in dark Vault colors — replacing the shelf art, per the changed pick.", "Settings: the checkmark item Saved collection count is now labeled Save collection count confirmation — same switch, same job, clearer name.", "Settings, Sharing: the Total collection value on your profile switch was dead — it buzzed but never changed. It now flips the instant you tap it and stays flipped, and a real save failure shows a plain error line instead of failing silently. The neighboring sharing switches were tap-tested too.", "Social now opens on Trades, and the friends list below the Trades, Marketplace and Forums selector is gone — the pinned Friends area at the top stays the one friends spot.", "Back-button cleanup: moving around the app — tabs, set pages, card pages, scrolling — no longer stacks a history entry per action, so three Back presses from anywhere get you out of Vault X and back to Muse, every time. An open window still takes the first Back to close itself.", "Library slab wall, take two: both slabs now render with identical geometry — same outer size, same slim label height, same cover proportions — so Batman and Aliens line up evenly like real slabs side by side. Label print at this size is not meant to be read.", "Library shelf: a Lorcana chapter binder now appears only when you own at least one card from that set — a set with nothing owned simply has no binder on your shelf, and the binder appears on its own when you add your first card from it. Same for promo binders: no owned cards, no binder."], "1.80.0": ["Achievements on profiles moved: the achievement icons now sit UNDERNEATH your name and verified badge instead of beside them, on every profile — and the row stretches all the way across the profile card, icons spread out instead of clustered. The row shows as many achievements as fit across the card, and any beyond that roll into a +N chip at the end; tap the row and the full achievements list opens, earned and unearned alike.", "Trust Score pill fixed: the highlighted box inside the Trust Score segment of the profile stat strip ran too close to the divider on its right. It now stops the same distance from the divider as it does from the left edge, and the Confirmed connections and Joined segments got the same even spacing.", "Library slab wall proportions fixed: the yellow grading label on the displayed slabs stretched far too tall at wall size, because the label is built at fixed print size. The wall now renders each slab at natural size and scales the finished slab down, so the label is the slim band it is on a real slab. Down at that size the label print is not meant to be read — the proportion is the point, exactly as directed.", "Zero means zero, loudly: anywhere an owned count is 0 — binder pockets next to the steppers, the per-finish counts on a card page, the Copies owned bar, game copies, sealed items — the 0 now shows BOLD and in the exact red of the minus button, so an unowned item jumps out. Non-zero counts look exactly as before, and the plus and minus buttons themselves are untouched."], "1.79.0": ["The Vault X server registry moved out of Settings and into Admin, where it belongs. Open Admin, tap Server Health, and the registry sits right at the top: your Collector ID, the username the server holds, your registration status and date, and when registration was last verified — all read live from the server, exactly as before. Settings no longer carries it."], "1.78.1": ["Back now closes the window you have open — full stop. The verified-badge explanation window used to let the phone's back gesture fall through to the app behind it; it now closes first, like every other window in the app. The same fix was swept across the few other windows that were missing it: a game card's detail page (Pokemon, Magic, Star Wars, Funko, Legos), the welcome page when re-viewed from Admin, the artwork download choice on the opening screen, and the example price-alert explainer. If a window is open, Back closes the window before it ever touches the page underneath."], "1.78.0": ["The verified badge is here: a small glowing check beside a collector's name on their profile, in friends lists, on Marketplace listings, and in the Forums. It is earned one way only — a trade that fully completes, both sides confirmed and feedback done, with someone who was already verified — so trust chains down from the owner and can never be self-granted or bought. Tapping any badge opens the story: how the badge is earned, and that collector's own proof, which trade earned it, with whom, and when. Two accounts start verified: ARuikis as owner and root of the chain, and Jarvis as the built-in friend. The owner can also verify someone by hand from Admin — their proof then honestly reads Verified by the owner with the date — and can revoke a badge on a substantiated report. One honest limit, stated right in the explainer: verified means identity confirmed on the network, never safe to pay; the in-person QR handshake stays the safety step.", "Forums are LIVE in Social — no Coming Soon gate. The home defaults to the latest activity across all seven categories (Announcements, General Talk, Show-offs, Deck Talk, Grading and Pricing, Trading Corner, Help and Rules), with a category chip rail, search, and Latest, New, and Top this week sorts. Threads are flat and readable: avatar, name, role chip, verified check, and a trust strip showing confirmed trades on every post. Up to two threads can be pinned at the top. Forum roles — Moderator and Admin — are granted only by the owner, and only to verified collectors: lose the badge and the role is suspended with it, until verification is restored and the role is granted again.", "Admin is now the Hub: six big tiles — Users, Activity, Trades, Tickets, Catalog, Server Health — each with its headline number and a trend cue, and each opening the full detail view behind it, with everything Admin showed before and nothing dropped. Changed areas still light their tile until you look. Catalog finally gets its own detail view: printings cataloged, sets, the daily audit's last run, and every game catalog's progress. A new Photos needed for approval block appears whenever accessory photos are waiting, opening a one-by-one review screen.", "Invite lineage, owner-only: the Share Vault X message now carries your own invite code, and when a newcomer registers with it, Admin records who vouched them in and when — and each collector's Admin detail lists everyone they have vouched in, so a swarm under one name is visible at a glance. It never appears on any public profile, and it never grants or feeds the verified badge — an invite proves you know somebody, not that you are trustworthy.", "Marketplace grows behind its Coming Soon gate: selling is now verified-only, enforced on the server — browsing stays open to everyone. A new Other item listing type covers Lorcana accessories — playmats, oversized cards, lore counters, pins, deck boxes — with your own title, description, category, price, and a required photo of the actual item. There is no market comparison on accessories because nothing tracks one; your price stands alone. The listing goes live immediately, but the photo is gated: buyers see a Photo pending approval placeholder until the owner approves it in Admin, and a rejected photo can be replaced from Your Listings, which re-enters the review queue.", "Portfolio's value graph gets its own titled box — Portfolio Value, in the same title-bar style as Movers — with the range buttons reworked as a proper pill group inside the box, a smoother curve, and cleaner labels. Track and Research moved to directly below the graph, where it belongs.", "The plus and minus steppers are now split by color, everywhere in the app and in every theme: green glow for plus, red glow for minus — same hollow-glow rings, same size inside the pocket, same big touch area and hold-for-a-number dial. Only the colors changed, and they never change with the theme.", "Card pages are deduped: the Card tab is now only about the card itself — stats, your copies, Where it lives, steppers — and everything financial (the value graph, per-finish values, average market value, what you paid, price alerts) lives only under Card Performance. The one exception stays exactly where it was: the TCGplayer link on the Card tab, so you can still jump straight out to buy the card.", "Smaller polish: Home's Top Movers shrinks one more step with names and figures still fully legible and the equal spacing kept; the Home shield and envelope badges get the full gradient-and-glow theme treatment with their counts in the new pill style; and the intro screen now offers a choice when new caching is pending — download it all up front with a real progress bar in megabytes and percent, or opt out for good and let images cache as you scroll. Nothing is ever forced, and you are never locked out.", "Search refresh is fixed for good: pull-to-refresh while on the Search tab now shows Search from the very first frame, with zero flashes of Home. Search was the one tab the refresh cover missed — its saved view is now restored before the first paint and painted above everything else, so Home never gets a single frame.", "The full Lego catalog is downloading into Vault X from Rebrickable, the standard Lego catalog source: 28,565 sets with set numbers, names, themes, years, piece counts, and set photos, shelved under their top-level theme. It lands in resumable chunks like the other catalogs, and a daily schedule keeps it coming until it is complete. That source publishes no prices and no per-set minifigure counts, so neither is shown rather than guessed. Lego sets track Sealed copies apart from Opened copies, because that distinction drives Lego value — mark either from a set page, and your sealed sets gather on their own shelf in the Legos section.", "The Legos tile is live: its Coming Soon label is off, its artwork is the open vault of colorful bricks you picked, and tapping it opens the Legos section while the catalog keeps downloading in the background. The Lorcana tile gets the storybook artwork you picked — the open book with cards around it and golden light rising off the pages. The chapter artwork inside the Lorcana section is untouched.", "Library news: Funko and Legos each get their own signed shelf in the Library, with a spine for every line or theme you own at least one item in — opening a spine takes you to that line or theme in its section, with your owned items marked. This Library treatment for Funko and Legos is provisional: it gets revisited once you have added a few of your own items and seen it with real pieces in it.", "Library Comics is a display wall now instead of a binder: your chosen graded slabs hang on the wall as rendered slabs, up to five of them, and you control the lineup from Edit display. Yours starts with exactly your two signed comics — Aliens #1, signed by Sigourney Weaver, and Batman #136, signed with a sketch by Tyler Kirkham. Tapping a slab opens its detail view as before, and the Comics section itself is unchanged.", "Watchlist and Alerts now cover any cataloged item, not just cards: Funko figures, Lego sets, the other game catalogs, sealed products, and graded comics can all be watched from their detail views and managed in Portfolio. The honest limit: an item with no tracked price on TCGplayer or eBay sold can be watched but not alerted, and its page says so plainly instead of offering a button that could never fire.", "The long-press number picker is on theme at last: hold a plus button and the 1-to-9 dial now wears the shared Vault X panel treatment — dark surface, accent glow, generous rounding — in every theme including Rainbow, everywhere the picker opens. How it works is unchanged: pick a number and it saves, tap away or press back and nothing changes.", "Settings cleanup: About this app and App updates are one tile now. The version line and the Check for Update button live together at the top of Settings, everything the old updates tile showed sits behind the small i button beside it, and the separate App updates tile at the bottom of Settings is gone. Seeing the welcome page again moved, too — it lives in the Admin Hub now, as a View welcome page button.", "Social settles into its final layout: Friends is pinned at the top of Social with the friend rail and your Trust Score line, always in view, while Trades, Marketplace, and Forums swap in the space below. Tapping the Friends card header opens the full Friends view with the registry and the complete list."],"1.76.0": ["Portfolio grows the Track and Research block you approved, right under the Re-price pills: one pill dropdown — Watchlist, Alerts, Research — and the area below it swaps to your pick. Watchlist holds anything you are eyeing, owned or not, with its price, day change, and trend line; add items with the new Watch button on any card or sealed page, and tap the bell on a row to set an alert on it. Alerts is now the one home for every price alert you own, the same list the item pages create, with triggered ones flagged red and a red count badge on the menu when any have fired. Research is the homework page for one card: full price history chart, TCGplayer next to eBay with the last-sold figure and its date where sales are recorded, your position, every printing compared, and what finishing its set would cost.", "The color at the top of the app now holds your theme on every tab — Home, Search, Social, Portfolio, Settings — with no flip as you move around, and the trip into Search arrives in one smooth fade instead of a rough cut. Under the Rainbow theme, the last flat-blue stragglers (the change-request Bug and Idea toggle and its Send button, the About box buttons, Check for update, and every other gold primary button) now wear the blue-to-violet Trades gradient like the rest of the app.", "Hyperia City's Full Puzzle Art is fixed: it now shows the genuine assembled artwork photo from the set's own Set of 9 product, and this update also clears out stale saved artwork on your device so an old wrong image cannot linger. Every other set's Full Puzzle Art was re-checked against its own pieces the same way.", "The plus and minus stepper rings in the collection are smaller — same perfect hollow glow, now sitting fully inside the card pocket borders with room to spare, in two-across and four-across grids, on sealed items, and on item pages. The big invisible touch area and the hold-for-a-number picker are unchanged.", "Settings no longer carries a Your Collections section — that control lives in exactly one place now: the eye button beside Your Collections on Home, whose window holds all seven collection toggles, Funko included.", "The Funko tile gets the artwork you picked — the three cased figures on the shelf. One honest note on its label: the Funko catalog has actually landed (23,939 figures, browsable in the Funko section right now), so under the rule you set — label on until the catalog is live, off once it opens the real section — the Coming Soon label has graduated off. Tap the tile and the full catalog is there."], "1.75.0": ["Home launch, rebuilt for speed: Vault X now keeps a copy of your last-seen Home on this device and paints it whole in the very first frame when you open the app — your Collector ID pill, the portfolio pill, Top Movers, and Your Collections all at once. Fresh numbers then swap in quietly behind that same screen. No more bits and pieces popping in one at a time, and the opening cover now only appears on a true first-ever run with nothing saved yet.", "The Marketplace is built out to the design you approved, still behind its yellow Coming Soon gate in Social until you say launch: every seller gets their own shop page inside the Marketplace with their listings, Trust Score, and confirmed sales count; listings are fixed price with one-tap Buy Now right on the tile as well as on the listing page; offers exist only where a seller flips the per-listing Allow offers switch, which starts off; the Sell screen shows your typed price against the live market value as you type; and when a sale completes and both sides leave their thumbs feedback, the sold cards now settle into both collections automatically, the same way trades and cash sales already do. An Under $50 filter joins the browse chips too."], "1.74.0": ["Funko Pop! joins Your Collections as a seventh tile, with its own artwork and a yellow Coming Soon label like the Legos tile. The full collector catalog is built in: every Funko figure tracked by Pop Price Guide and HobbyDB, with variants like Chase and retailer exclusives as their own entries, browsable by Pop! line and searchable by name, with owned counts just like the other collections. The catalog downloads in resumable chunks from the Funko section, and the tile's Coming Soon label comes off once the download completes. One honest gap: the open catalog data was last updated in January 2021, so figures released since then are not in it yet, and it carries no prices, so none are shown.", "Vault X is now multi-language: Settings has a new Language section, in the same themed dropdown style as Theme, with English, Spanish, German, French, and Japanese. Pick one and menus, buttons, and labels across the app switch right away, with numbers, dates, and currency formatted for that language. Card names and your own content always stay exactly as printed and as written. Any text without a translation yet falls back to English instead of going blank.", "The plus and minus count buttons got their fix and their glow-up: every stepper now renders as a complete hollow glowing ring, lit like the profile pictures on the Trades page and following your theme, with the plus or minus clear in the center. No more clipped, half-drawn circles, in the set grids at both densities, on sealed items, and in item details. The big touch area and the long-press number dial work exactly as before.", "Opening the app no longer fills Home in piece by piece: a themed cover holds for the moment your data takes to land, then the whole Home screen appears in one finished paint, portfolio pill, Top Movers, and collections together.", "The last two plain system dropdowns in the app, the set and rarity filters on the trade board, now use the same themed dropdown as everything else. No generic dropdown remains anywhere in Vault X."], "1.73.0": ["Your profile now always spans FOUR deck boxes across, empty or full: whether you have four decks on display, one, or none at all, the row is four boxes, each in a different color from the Vault theme - deep cyan, royal blue, violet, and magenta violet. Your decks fill the first boxes with their names on them, and the rest stand as plain empty boxes in their slot colors. On your own profile an empty box taps through to your decks page so you can add one.", "The little display window on deck box fronts is gone: no more featured card showing through the box face. Every deck box - on your profile and on the My Decks shelves - is now one solid color straight through, with its deck name still embossed on top.", "Opening a deck box shows the FULL card now: the featured card rises out of the box whole, at its real card proportions, instead of the half card that showed before."], "1.72.0": ["Your profile deck boxes are plain deck boxes again: the photos of your most expensive cards that filled the empty slots are gone, and only your active deck boxes appear, each with its deck name on the box.", "The deck box opening animation is cleaned up: the lid now tips back on its hinge like a real box instead of flipping forward, and the deck inside rises as the lid opens.", "Back from the Comics section now takes ONE press and lands back on your profile, the way it should - the same one-press return now works for every section opened from your profile.", "The Lorcana row in My Collection opens the chapters page, not the Library - the Library still opens from its shelf picture, as before.", "The Sealed row in My Collection opens the standalone Sealed page again - the acrylic shelf with the Owned and All toggle, set filter, and sorting. The Sealed tab stays off the bottom menu; the page is reached from your profile row."], "1.71.4": ["The little deck boxes icon inside the Library window on your profile is gone - your deck boxes sit right below that window now, so the icon was just taking up space. The Library shelf keeps its new bigger fit and stays centered, and the deck boxes below are untouched."], "1.71.3": ["The Library picture on your profile is sized to fit its window now: the binder spines stand taller and spread wider so the shelf fills the space instead of sitting small in the middle - and the whole picture stays centered, just like before."], "1.71.2": ["Moving your collections on Home is smooth now: hold a tile until it lifts and drag it, and it follows your finger cleanly while the other tiles glide into their new places - no more stuttering or jumping while you rearrange them."], "1.71.1": ["Two-across scrolling in set pages is smoother: the bigger tiles now use a right-sized 640px copy of each card saved on your device (your own collection is cached first), they decode without blocking the scroll, and the grid reserves the right height per tile so the page no longer jumps around while you scroll.", "The themed background now fills the whole screen on every page: scroll all the way down (the profile included) and the background continues to the edge - no more empty void band at the bottom."], "1.71.0": ["Full Puzzle Art in Hyperia City finally shows the artwork: no assembled photo of that puzzle exists in any source, so the entry now joins the set's own nine piece cards together into the completed picture - in the grid and in the card view.", "Every other set's Full Puzzle Art was audited too: The First Chapter, Rise of the Floodborn, Ursula's Return, Azurite Sea, Fabled, Winterspell, Wilds Unknown, and Attack of the Vine! all show their real assembled artwork.", "Shimmering Skies, Archazia's Island, Reign of Jafar, and Whispers in the Well have no assembled artwork published and no complete piece scans to build one from - the lore sets' pictures live on the card backs, which no source scans - so those entries settle on their name plate instead of sitting on Loading art forever."], "1.70.1": ["Prices that come from eBay sold listings now say so right on the item in the missing list: recent sales read 'eBay sold median' with the dates they sold, and once the sale behind a price is more than about 90 days old the line switches to 'Last sold at that price on eBay' with the month - a stale price is never dressed up as a current one."], "1.70.0": ["Set pages now open two cards across by default, big enough to catalog by scrolling: the regular and foil pockets sit side by side, and each pocket has its own minus and plus stepper right on the grid - tap to add or remove a copy without opening the card, or hold the plus to pick a count.", "A 2 across / 4 across toggle sits at the top of every set page in every collection - Lorcana chapters and promos, Pokemon, Magic, and Star Wars Unlimited - and your choice is saved to your profile, so it follows you. Four across stays for fast hunting.", "Curator's Collection: Beauty and the Beast promos are priced now from recent eBay sold listings (median sale price): Be Our Guest $39.99, Belle $69.99, Lumiere $29.99, Gaston $28.99, and Beast $60.00 - so that set's cost to complete finally shows a real number.", "Mrs. Potts (2/CC2) has no recorded sale anywhere yet, and Promo Set 4, Ravensburger Play Hub, and Challenge Series 3 still have no eBay sales to price from - those stay honestly marked as having no tracked price rather than a made-up one.", "Prices now follow your hierarchy everywhere the app prices a card: TCGplayer first, and where TCGplayer has no price, the median of recent eBay sold listings - asking prices never count."], "1.69.0": ["The whole app now lives in the Trades world under Rainbow: every page sits in the same lit backdrop of soft blue and violet glows, cards read as raised panels with a lit top edge, and inset boxes like text fields share the same tones instead of sitting as flat dark patches.", "Portfolio joins that world too: the Total Value hero and the value chart card now use the raised Trades panel look with its top glow and hairline border, the chart grid is softer, and the Home Portfolio pill matches.", "Settings is fully in the theme now: Send a change request, Share Vault X, Username, and App updates - including their inner boxes and fields - all carry the same depth and glow as the rest of the app.", "Buttons and highlights everywhere now wear the blue-to-violet gradient with its glow, the exact treatment from the Trades page.", "Set complete now reads like the achievement it is: on finished chapter, promo, and Illumineer's Quest tiles, the label is rich gold with a warm glow instead of plain text."], "1.68.0": ["Your profile got the cleanup design you approved: your photo sits centered with a glowing ring and its edit button on the photo itself, your @username and bio centered under it, your Collector ID QR small in the corner of the card (tap it for the big scannable view), one full-width Edit Profile button, and one stat strip with Trust Score (tap it for the breakdown), Confirmed connections, and your joined month.", "Your profile now has four boxes under your Library picture: they are your deck boxes - each one shows the featured card you picked for that deck in its window - and any box without a deck showcases one of your most valuable cards instead, with its value stamped underneath. Tap a deck box to open that deck; if you ever have more than four decks, an All my boxes link opens the full My Decks page. Your Library picture itself stays your binders, exactly as before.", "Fixed the tile drag for real this time: the page was stealing the gesture - a held tile lifted, moved a millimeter, and then the whole page scrolled. Now, the moment a tile lifts, the page scroll is locked until you drop it, while a normal scroll starting anywhere else still works as always.", "Rainbow now carries the whole Trades look across every page: surfaces have that gradient depth, cards and pills take the rounder bubbly curvature, profile pictures glow, and buttons carry the blue-violet glow - the full treatment, everywhere.", "New My Collection section on your profile, built from the design you approved: the Lorcana row carries a big glowing completion bar with your unique-owned count and total cards, your chapter closest to finished gets its own row with its bar and exactly what it costs to finish, and Comics and Sealed rows sit beneath - every row taps straight into that part of your collection."], "1.67.0": ["Trades is rebuilt in the new design you approved: Best Matches shows each friend with what you can get and what they can get (exact printings, both ways) and a balance bar, and Browse Cards pools every available printing into one board with direction, set, foil, and rarity filters and sort by value. Tapping a card starts a trade with its owner. Trade Match itself stays on your friends profiles.", "New theme: Rainbow. The Trades colors - deep navy, blue and violet glows - now carry across the whole app when you pick Rainbow in Settings, and it is set as your theme. The other five themes are unchanged.", "Fixed the Your Collections tile drag: hold a tile until it lifts, drag it with your finger over another tile to swap places, and let go to drop it - the other tiles glide out of the way, and your order is saved."], "1.66.0": ["Your Collector ID page is display-only now: the photo changer box at the bottom of that screen is gone - it just shows your QR code, Collector ID, and username.", "Change your profile photo right on your profile: a small edit button now sits on the photo itself - tap it to pick a new one.", "New Edit profile on your own profile: change your photo, edit your bio line (it saves to your profile now), and manage your banner, all in one place. Username changes still live in Settings, where they can be changed once."], "1.65.0": ["The Home Portfolio pill graph is now a smooth, rounded curve - the bubbly line from the design you approved - instead of sharp straight segments, with the same soft gradient fill underneath it.", "Top Movers on Home tightened a little more: slightly shorter rows and smaller card thumbnails, while card names and their gains and losses stay full size and easy to read.", "Even spacing on Home: the gap between Top Movers and Your Collections now exactly matches the gap between the Portfolio pill and Top Movers, so the three blocks stack evenly and Your Collections rides up with the shorter movers."], "1.64.0": ["Home snapshot: a slim Portfolio pill now sits near the top of Home - a mini value graph with your total and its change across the tracked history; tap it to jump straight to Portfolio. Right under it, Top Movers lists the three cards in your own collection that moved the most in the last 24 hours, gain or loss; tap one to open that card.", "Portfolio Total Value box redesigned from the ground up: a deep dark hero block with a soft blue-purple glow along its top edge, the value big and fully formatted (commas and cents, the cents set smaller), your period change as one tinted chip under the value that follows the range selector, the stat strip below a hairline, and the priced-as-of line demoted to a small footer showing the actual latest reprice date instead of the old stale headline.", "Search in every section: Lorcana, Pokemon, Magic: The Gathering, Legos, Comics, and Star Wars Unlimited now share the same top row - a search bar styled to match the Scan pill with its own magnifier icon, and the Scan pill at the top right. Each bar searches its own section's catalog; the Lorcana bar hands off to the full catalog search, which hones in with name plus collector number.", "Smoother binder scrolling: card pockets far off screen now skip their layout and paint work until they approach the viewport, so long set grids scroll lighter. Nothing on screen changes.", "Buy handoffs confirm first: Buy missing cards and the deck buy list now show exactly what will be sent and where (TCGplayer, via Jarvis) before anything is handed off - nothing leaves the app until you tap Send on that confirmation.", "Home pill, final layout: the text group (label, total, and the change as a small tinted chip) is centered together, the mini graph starts right after the numbers and fills the rest of the pill to its right edge - never running behind the words - and the pill shows the same grand total as Portfolio.", "Home tidy-up: the Top Movers rows are condensed about 30 percent, Your Collections now sits snugly right under them, and the Collection Value figure beside the Your Collections heading is gone - the total now lives in the pill, shown once.", "Portfolio's value chart now wears the Total Value box's theme: the same deep dark block with the soft glow along its top edge.", "Reprice Force joins Re-price now in the Total Value box: the normal button runs the day's re-pricing (once a day), and Reprice Force starts a fresh run on the spot even when today's already ran."], "1.63.0": ["Fixed: the Home tab now always lands on the actual Home screen. It could greet you with your name and QR code instead - the big QR view now opens only from your profile (tap your name pill to open your profile, then the QR / Collector ID element there), and tapping Home closes anything stacked above Home.", "Fixed Trade Match: it matched cards by NAME, so cards a friend holds as a different printing - or a foil you only have in regular - never showed. It now compares exact printings (set, number, and finish) both ways, with the match counts shown. Jarvis's Elsa - Snow Queen Cold Foil and his Stitch - Rock Star printing now show next to his Mickey Mouse - Brave Little Tailor.", "Trades tidy-up: the moment a trade offer or purchase order is done - declined, withdrawn, or completed with feedback wrapped up - it files itself into the new History section at the bottom of Trades, and finished deals already on the books moved there too. History stays collapsed until you tap it, records are kept for good (they feed Trust Scores), and you can also archive any finished deal by hand with its Archive button. Active and pending deals never move."], "1.62.0": ["My Decks: the deck box is redesigned to look like a real deck box - a solid molded box in your chosen color with a lid seam under the embossed name and a small window in the front panel. The window shows a close-up of the featured card's face and art, not the whole card. Your Village Aggro box now features Mickey Mouse - Best in Town in its window, and you can change the featured card any time in the deck builder.", "Settings: the Username section now has its own icon beside its heading - a person mark in the same style as the other section icons. Nothing else about the username box changed."], "1.61.2": ["Home: the Your Collections section and the collection value beside it now sit noticeably lower on the page - a clear step down in the space above the section, with the value moved down to match. Nothing else on Home moved."], "1.61.1": ["Home polish: the Legos tile now reads Legos with Coming Soon beside it in smaller print on the same line, so the tile is the same height as every other tile and the row lines up evenly wherever the tiles are dragged.", "The Your Collections section sits a little lower on Home (about a fifth more space above it), and the collection value total beside it nudged down slightly to match.", "Your name and Collector ID oval at the top of Home is now pinned flush to the right edge, in line with everything else on that side of the page. It still opens your profile.", "Settings cleanup: the row of quick-jump icons under the About box is gone. Every section keeps the icon beside its own heading, and the Vault X server registry section has a new icon of its own - a server stack inside the Vault ring."], "1.61.0": ["Fixed: refreshing while on Search now stays on Search - it restores in place before the page paints, with no detour or flash through Home, and the keyboard still never opens on its own.", "Your name at the top of Home now opens your profile directly again - no page in between. The big scannable QR view opens from the QR / Collector ID element on your profile, and Back returns to your profile.", "The Trust Score breakdown has a new home: tap the Trust Score line on any profile (right under the joined date) to open the breakdown page - what the score is made of, verified events only. The QR view now shows just the number.", "Settings: Theme is now a proper drop-down in the Vault X style - tap it, pick from the themed menu, and it applies and saves as before. Your Collections in Settings is a matching drop-down box that expands to the same six show/hide switches."], "1.60.0": ["Three new collections open: Pokemon, Magic: The Gathering, and Star Wars Unlimited lose their Coming soon labels and each opens its own section - browsable by set and card number like Lorcana, cards ghosted until you mark copies owned, with search across the whole catalog. Their catalogs download in chunks from their official free sources (Pokemon TCG data, Scryfall, and Fantasy Flight for Star Wars), and each section shows the download progress honestly until it is complete.", "Friends is now a MySpace-style grid: just each friend photo with their name underneath, nothing else - tapping still opens their profile.", "Lego is now Legos, everywhere the collection label shows. The Legos section itself is untouched.", "Your identity page (tap your name at the top of Home) is now just your big QR code, your username, your Trust Score breakdown, and the link through to your profile. Username editing moved to Settings - and you can change your username one time only, so the Settings box says so plainly and locks after one change. Your server registry entry moved to Settings too."], "1.59.0": ["Admin: Registered Collectors is now called Registered Users everywhere in Admin, and that list is redesigned - clean, roomy rows with the avatar and username up top, the Collector ID underneath, and one tidy line for Trust Score, items collected, connections, and joined date.", "Search: the search box is back up at the top of the screen, right under the Search heading, where it looks right. It still only opens the keyboard when you tap the field.", "Social: Add a friend by code now sits right under the Social heading as a quick add - just the code field and the Add friend button, nothing else - and it is gone from down in the Friends list."], "1.58.0": ["New: rearrange your Home collections. Hold any Your Collections tile and drag it to a new spot - put Magic first, or any order you like - and the app remembers your order on your profile. Hidden tiles stay hidden and the rest reflow in your order; a normal tap still opens the collection as before.", "Removed the Marketplace from the bottom of the Home screen - it is gone from Home entirely. The Marketplace still lives in Social, exactly as before."], "1.57.7": ["Removed the Marketplace from the bottom of the Home screen - it is gone from Home entirely. The Marketplace still lives in Social, exactly as before."], "1.57.6": ["Removed the Two pockets for every card number note from the bottom of the Home screen - it is gone entirely, for you and for every other collector."], "1.57.5": ["Collection Distribution moved, as you directed: it is gone from Home entirely - no copy, no summary left behind - and now lives in Portfolio in your final order: the value graph, then the Collection Distribution, then the Movers. Same rows, same percentages, same total underneath it all.", "The Queen, diagnosed end to end this time instead of guessed at: her catalog entry is correct (Promo Set 3, printed 3/P3, your two Promo Cold Foils), she is in the scanner plan's priority list, and her artwork loads fine - those stages were never the problem. The drop was in the trust rule: your phone only trusted a sure on-device match if ALL roughly 3,700 card fingerprints had finished building, which takes a very long time, so her match kept being handed to the server read - the one measured at 18 to 25 seconds - and died at the time limit in every version. Now a sure match on a promo printing stands on its own as soon as the promo tier (which builds first) is complete, so scanning her can finish in about a second on the phone's own match. Please re-scan The Queen after updating and give the app a little open time first if the scanner still shows the index building - her tier is the first one it builds."], "1.57.4": ["Scanner, rebuilt around your five-second rule: a scan now NEVER runs longer than five seconds, period. Your last tests ran 30 and 31 seconds, and one of them ended with no suggestions at all - both of those are fixed at the root. The old build waited on the server read, which takes far longer than five seconds, and threw the wait away at the last moment; the scan now lands at about four and a half seconds with the best matches your phone itself found, so you always get picks to choose from instead of a spinner.", "The server check also starts the moment you take the photo - it is already running inside the first second or two, not at three or four seconds - and the server itself now stops at four seconds. A sure on-device match still answers in about a second, exactly as before. And if a scan ever does stop at the limit, the closest matches from your phone are shown below the note, never a bare empty list.", "Please re-scan The Queen (Promo Set 3, number 3) after updating: the scan should finish inside five seconds and offer her among the picks if your phone index has her artwork - and the search on the result screen (try The Queen 3) is there if it does not."], "1.57.3": ["Portfolio, aligned to the example you approved: the header is now exactly the mockup - Total value, its change line right beneath, then the five labeled figures (Paid, Net, Cards with unique count, Graded, Sealed) as clean cells. The extra text that had crept into the header is gone from there (the foil and spare-copies note now sits at the bottom of the page), the long explanation paragraph under the chart is one short line, and the breakdown choices are a simple row of pills like the example - so the page reads value, trend, movers, breakdowns, sets, in one scroll, the way the example showed it.", "Settings cleanup, as you directed: the Admin section is removed from Settings (your Admin still lives on Home behind the shield badge, with every statistic), and the Tickets list is removed from Settings too - tickets live in your Inbox only now. Send a change request stays in Settings; it is the form tickets are sent from. No Tickets icon was added anywhere - you decided that would be redundant with the Inbox."], "1.57.2": ["Scanner fix, after your Queen test failed again: this time the failure was measured, not guessed. The server read of a card photo actually takes about 20 seconds - the old scan gave up at about 14 seconds and showed you only your phone closest artwork guesses, which is why a bunch of cards appeared and The Queen was never one of them. The read itself was perfect when it was allowed to finish: exact title, and the collector line read as 3/P3.", "What changed: the server check now starts the moment you take the photo (not after the on-device match), the reading prompt is focused so the read comes back faster, and a scan that needs the server is allowed up to 32 seconds before it stops - the waiting screen now says the server route can take up to about half a minute. A sure on-device match still answers in about a second, exactly as before.", "Please re-scan The Queen (Promo Set 3, number 3) after updating: she is the test case. The scan should now land on her exact printing, or offer her among the printings to pick from."], "1.57.1": ["Portfolio check, after your report that the new layout still was not showing on your phone: the rebuilt Portfolio (one scroll, one range selector driving the change line, the chart, and Movers together) is confirmed in this version - tap Portfolio and you should see your total with its range change right beneath it, the 7d / 30d / 90d / 1y / All pills above the value chart, and Movers under the chart. If your copy still shows the old Portfolio, use Update now here rather than a pull-to-refresh - a plain refresh can be answered from your phone cache with the old version, while Update now fetches the fresh build first.", "Also fixed in the Portfolio per-set table: every set was showing 0.0 percent complete and Complete - nothing to buy, because the table was reading the Puzzle rows that share each set name instead of the set itself. It now shows each set real completion and cost to finish (for example Hyperia City at about 74 percent with its real cost to finish)."], "1.57.0": ["Scanner rebuilt the internet way, the option you approved: when your phone is not sure about a card, it now sends the photo to the server with its closest artwork matches, and the server reads the tiny collector line at the bottom of the card (like 3/P3) and uses that exact line to pin the printing. That is the check that can find The Queen, Promo Set 3 number 3, even on a phone whose on-device card index has not finished building - her artwork twin in Fabled and the Epic share her name, but only her promo printing carries the line 3/P3.", "A sure match on a finished on-device index still answers in about a second with no server call. Anything less than sure now takes the server route, which can take a few seconds longer; the whole scan is allowed up to 15 seconds instead of 10 so that read is never cut off mid-check.", "When more than one printing still fits after the line check, the pick list now shows up to eight printings instead of four, so the right one is not cut off the bottom of the suggestions."], "1.56.0": ["Portfolio rebuilt to the layout you approved: one scroll, one range selector. The 7d / 30d / 90d / 1y / All pills above the value chart now drive everything together - the change line under your total, the chart window, and the new Movers list of your top gainers and losers (tap a mover to open the card).", "The header is tighter: your total, its change for the selected range right beneath it, and one stat strip - total paid, net, cards with unique printings, graded, sealed - plus an eye button that hides the money figures when you show the app to someone. The chart also gained an optional Paid line, off by default.", "Breakdowns now switch in place on the same page (no separate pages to back out of), with a new By Type pill - Singles / Graded / Sealed. The per-set table gained Complete % and $ to Finish and sorts by net or completion, and Most Valuable now shows each item's share of your portfolio.", "Two honest limits: prices are only tracked from Oct 25, 2026, so for now the longer ranges measure from that first tracked day (the page says so where it happens) and will separate on their own as daily history builds. And there is no Recently Added strip yet - the app doesn't record the day each card was added, so rather than invent dates, that strip waits until additions are tracked."], "1.55.3": ["Promo tiles checked family by family against the price sources: the Curator's Collection Heroines (CC1) tile and the PD1 tile said 'no tracked prices yet', but those cards do sell on TCGplayer - their prices were pulled in, so CC1 now shows a real cost to complete and PD1 shows the cost of the four missing cards TCGplayer sells (the other five PD1 cards you need are not sold there and still count as unpriced).", "The other four families that say 'no tracked prices yet' were verified one by one and genuinely have no tracked prices anywhere the app can see: Promo Set 4's last missing card, the Ravensburger Play Hub set, Challenge Series 3, and the Curator's Collection Beauty and the Beast set - no marketplace the app tracks sells them, so the label stays for those four, honestly."], "1.55.2": ["Scanner: The Queen, Promo Set 3 number 3, could still slip past when the on-device card index had not finished building on your phone. The index now builds in the background whenever the app is open, not only while the scanner is open, so promos and puzzle inserts are fingerprint-ready long before you scan.", "Any scan that is not a sure match on a finished index is now double-checked against the full catalog reader at the same time, inside the same 10-second limit, and the two answers are combined - a card your phone has not fingerprinted yet can still be found instead of never appearing.", "The catalog reader no longer throws away a good card name over a misread of the tiny bottom line: the number after EN is the set number, not the collector number, and a read number that fits no printing of that name now falls back to the name itself, so the right printing still shows up in the picks.", "The picks list has room for more close artworks, so the card in your hand is easier to spot in the list."], "1.55.1": ["Scanner fix for The Queen, Promo Set 3 number 3: she was in the catalog all along, but the scanner could not reach her. Every promo printing now jumps to the front of the on-device index build, with the puzzle inserts, instead of waiting behind thousands of main-set cards - so promos are ready to scan within the first stretch of the build.", "Until your on-device index has finished building, every scan is now also checked against the full catalog reader and the two results are combined. A card whose fingerprint is not built yet can still be found, instead of silently missing from the list - and the result screen now tells you when a scan ran while the index was still building.", "The picks list is wider: the nearest few artworks always appear as choices when they are anywhere close, so the right card is there to tap even when it is not the top match. That helps close calls like the legendary Tiana too.", "If a scan still cannot place a card, its closest on-device matches are shown as picks instead of an empty result."], "1.55.0": ["Puzzle sections checked for every set, and the pieces have their artwork now. Attack of the Vine! has its Puzzle section at last: 9 pieces that assemble the Winnie the Pooh and Hunny characters artwork, Winnie at the centre.", "Puzzle pieces and Lore cards across the sets now show their real scans, and most sets' Full Puzzle Art shows the assembled artwork - Hyperia City's nine pieces included. Two Full Puzzle Art entries (Hyperia City and Reign of Jafar) still show a name plate because no assembled photo exists for them yet; their pieces all have art.", "Counts corrected from TCGplayer's own catalog: Azurite Sea's puzzle is 9 pieces, not 6. Winterspell has two insert series - 9 Lore cards and a separate 9-piece Snowball Fight puzzle - and Wilds Unknown's inserts are puzzle pieces. Into the Inklands is confirmed as the one set with no puzzle (its packs carried rules cards)."], "1.54.3": ["Scanner fix for the Ink Drop miss: your photo was clear enough - the matcher was not. It now compares the brightness pattern of the whole card as well as the fine detail, and it tries the card at more sizes and positions in the frame instead of only dead center, so a card sitting a little off-center still matches. On your exact Ink Drop photo the blue design now scores as the clear best match, with the gold design behind it.", "The Ink Drop counters and the other puzzle inserts now jump to the front of the scanner index build even when a build from an earlier open is still running, instead of waiting at the end of the queue."], "1.54.2": ["Ink Drop counters can be scanned now: the two Hyperia City Ink Drop counter cards are fingerprinted first when the scanner index builds instead of last, and the backup reader now knows Counter cards are real catalog items even though their printed text says the counter does not count as a card. When a scan reads an Ink Drop, you pick between the gold design and the blue design, so the exact one in your hand is the one that gets added.", "Auto capture is quicker: it fires after about half a second of a clear, steady card instead of a second or more, camera brightness shifts no longer count as movement, and one small tremor no longer restarts the wait from zero. It still will not fire on a blurry frame."], "1.54.1": ["Scanner screen fixed: the camera and the Capture button now come first, so the Capture button is always on screen when the scanner opens - no scrolling past a wall of text to reach it. The long how-it-works explanation and the on-device index status moved into a short How scanning works section under the buttons; tap it only if you want the details."], "1.54.0": ["Scanner rebuilt: matching now happens on your device. Your phone keeps a small fingerprint of every card artwork (built from the artwork already saved on the device, at no cost and with no outside service), and a scan compares your photo against all of them in about a second instead of sending it away and waiting.", "When several printings share the same artwork - reprints and promos a fingerprint cannot tell apart - you get the list and tap the exact printing in your hand. That tap is how the right printing is chosen, so a scan can no longer confidently name the wrong printing.", "The scanner shows its on-device index progress while it builds in the background. A photo the device cannot place at all (like a whole binder page) still uses the older slower reader, and the result says which one matched. Auto capture, the frozen snapshot, the 10-second stop, and search on the no-match screen all work as before. This is a first trial of the new matcher - scan some real cards and tell Jarvis how it does."], "1.53.0": ["New: Auto capture in the card scanner. Hold a card in the frame and the photo takes itself the moment the card is sharp, steady, and close enough to read - no button tap needed. The viewfinder tells you what it sees as you line up (too dark, glare, not sharp yet, hold still) and the frame turns gold, then green, as the card gets clear enough.", "Auto capture is on by default and can be switched off right above the Capture button - the manual Capture button and the photo button work exactly as before either way."], "1.52.0": ["Trades and cash purchases now settle themselves: when a deal is fully complete — both sides confirmed and both feedbacks in — the cards each side gave come out of their collection and the cards they received go in, automatically, using the deal's own agreed lists. No re-entering quantities anywhere.", "Every trade now carries a note at the very bottom: Once this trade is complete, the new quantities will be reflected in your sets — there's nothing further for you to do. Completed deals show a Settled into your sets line once their quantities have landed.", "Fixed: Back from an opened deck now returns to your deck boxes — only Back from the decks page itself returns to your profile.", "Fixed: refreshing while in your profile, Library, or My Decks no longer flashes the Home screen first — the page you were on is covered from the first frame and reloads in place.", "Admin: tapping a highlighted change now clears it immediately, in place. A new What changed panel at the top of Admin lists every change in plain words with its old and new values, and the changed tiles and roster rows carry the same readout, so the badge count maps to exactly that many readable changes."], "1.51.0": ["Swipe between tabs is gone: it worked, but Anthony did not like it, so tabs switch by tapping the bottom bar again and the slide animation went with it. The Library binder's finger-swipe page flipping is a different feature and is untouched.", "The active tab highlight in the bottom bar is now a boxier rounded rectangle instead of the in-between oval pill — same blue-purple glow, new shape.", "Fixed: tapping the empty space on the My Decks page no longer throws you back to your profile. Only the deck boxes and the real Back and Close buttons navigate now.", "The Library shelf on profiles is centered by construction now — its middle sits exactly halfway between your profile picture's edge and the deck box icon's edge, worked out by the layout itself instead of by nudges.", "Scanner: identification now has a hard 10-second stop — it can never spin for half a minute again — and when it stops it lands on the no-match screen with the catalog search right there. The reader now also understands promo collector lines like 20/C2."], "1.50.0": ["The daily catalog audit now shows its last run in Settings under Your data and backups - when it ran and how many printings it added.", "Promo tiles now carry the same progress bar with owned counts as the chapter tiles, and their Cost to complete uses real promo prices - families with no tracked prices say so instead of showing zero dollars.", "The Hyperia City Ink Drop counter cards are in the catalog and sit in the Puzzle section at the very end of the Hyperia City list.", "Refreshing on your own profile now reloads your profile in place - no more disappearing to Home and back.", "Every dropdown in the app has one clean modern look now - dark, rounded, with a check mark on the current choice - instead of the old grey system menus.", "Slab labels: the white box around the 9.8 is now an equal square like the real CGC labels, and White Pages no longer sits under the grade on Universal slabs.", "The Library shelf on profiles was nudged right so it sits truly centered between your photo and the deck box.", "Your Village Aggro deck is built and on display in My Decks: all 60 cards from your collection, with its value taken from your own inventory, and every copy in the deck marked in Where it lives as living in the Village Aggro deck box.", "Refreshing while you are in My Decks or your Library now reloads that page in place instead of bouncing you to Home."], "1.49.0":["The card catalog is now complete: a full audit against every Lorcana card ever released added 40 missing promo printings, each with its real artwork, so every one can be scanned, searched by name and number, and added to your collection.","Challenge C2 now runs all the way to number 20, including Minnie Mouse - Amethyst Champion 20/C2, the card that started the audit. Searching Minnie 20 finds her.","Two whole promo families are new: Challenge Series 3 (C3, 17 cards including the serialized Hades - Dark Usurper prize printings) and the Beauty and the Beast Curator's Collection (CC2, 6 cards). Also filled in: the serialized Mickey Mouse - Brave Little Tailor 5/C1, Baymax - Lab Assistant 5/DIS and Creative Inspiration 19/DIS, Mickey Mouse - True Friend 15/P2, Elsa - Queen Regent 16/P2, Anna - Braving the Storm 17/P2, and Donald Duck - Taxi Driver 1/P4.","A catalog audit now runs every day on its own: when a new set or promo printing is released and published by the card databases, it is added to the catalog automatically. Your existing cards, ownership counts, and prices are never touched by it."],"1.48.1":["Fixed: the Collector ID card at the top of Home could get stuck on Generating when its saved profile photo could not be read back from storage. A photo or banner whose stored copy is missing now simply shows the plain initial-letter card instead of failing, and card artwork whose stored copy is missing is fetched fresh again rather than erroring."],"1.48.0":["Scan a card, rebuilt for speed and accuracy, and this was the top-priority fix. Taking a photo now freezes the snapshot on screen with a shutter flash, so you can see the exact photo being identified, and Identifying shows a live timer and what stage it is on instead of a silent pause. If a scan runs long you can cancel it, and at 45 seconds the wait stops on its own with your photo kept and Try again and Retake options. Matching is stricter now: a card is only named for sure when the title, number, set, ink color and cost read from the photo agree — when a read could be more than one printing, you pick the right one from the candidates instead of being handed a wrong card, and every certain match shows what was actually read from your photo so a misread is easy to spot. A card outline in the viewfinder helps fit one card in the frame, and scanning another card now keeps the camera live instead of going black."],"1.47.0":["New: copy a deck. Open a deck box on another collector profile and tap Copy to My Decks and check my collection: the deck lands in your My Decks marked Copied from that collector, and you get a check against your own collection — you have X of the deck, you need Y more — with a card-by-card breakdown, a buy list of just the missing copies, and what they would cost at current prices. On the buy list, Send buy list to my Muse (or Send on a single card) hands your own Muse the exact missing cards to build a TCGplayer cart under your sign-in; Vault X never buys anything itself and final payment approval stays with you. Your own decks get the same collection check from their deck page."],"1.46.0":["Price alerts now have their own page: tap the Price alerts heading at the bottom of any card, sealed product, or graded comic and you get every alert you have set, all in one list, each with its picture, its current price, and the price you are watching for. You can edit any alert right there (change it to at or below or at or above a new price) or delete it, and Back takes you straight back to the item you came from. Graded comics can have price alerts now too, set from the Performance tab on a comic page, and a triggered comic alert banner on Home takes you to your comics."],"1.45.3":["The Comics shelf sign in the Library got the comic-book treatment: Comics now sits on a deep-blue halftone-dot plaque in bold yellow block lettering with a black outline and a red offset shadow, tilted like a classic comic masthead. The Lorcana wordmark signs and the Promos sticker sign are unchanged."],"1.45.2":["Refreshing on the Admin page now reloads Admin in place: refresh while Admin is open, or while the Registered Collectors page is open on top of it, and you land right back on that same page with everything as it was, instead of being thrown back to Home."],"1.45.1":["Admin opens fast now: tapping the Admin badge shows the page right away with your last-known numbers, labeled with the time they were computed, while the fresh numbers load in the background and swap in when they land. The heavy server work behind Admin also runs in parallel now, so the refresh itself finishes much sooner too."],"1.45.0":["Admin: the Registered collectors tile now opens its own full page — one detailed row per collector with their username, Collector ID, Trust Score, items collected, confirmed connections, and the date they joined, all live from the server. Anything the registry does not track is labeled as such instead of guessed. Back from that page — its Back button or the phone back gesture — always returns to Admin, never out of the app."],"1.44.0":["All card artwork now saves to your device up front: after the welcome tour, a background pass downloads every card picture — your own collection first, then the whole catalog set by set — so browsing never waits for images to load. It never blocks the app, and Settings under Your data and backups shows exactly how many images are saved on this device. When an update brings new or refreshed artwork, the new copies save on their own and replace the old ones."],"1.43.5":["The three Illumineer's Quest tiles — Deep Trouble, Palace Heist, and The Great Hunny Rescue — now carry the same rich, edge-to-edge key art as the premium chapter tiles like Hyperia City and Attack of the Vine!: Ursula with her trident and eels for Deep Trouble, Jafar wearing the Reforged Crown for Palace Heist, and Winnie the Pooh the Hunny Archmage with his friends in the Vine for The Great Hunny Rescue, all from the official high-resolution quest artwork. Tile size, names, and progress lines are unchanged, and the quest box art still shows on the quest pages themselves."],"1.43.4":["Your Inbox now marks anything you have not opened yet with a bright blue NEW badge right next to its subject, so read and unread are easy to tell apart. Opening a message clears its badge the moment you open it, even if you have not answered yet — the Pending label stays exactly as it is until the order, trade, or ticket actually finishes. The number on the mail icon on Home now matches the number of NEW badges in your Inbox, and a new reply in a thread you already read makes it NEW again.","Share Vault X in Settings has moved: it now sits directly underneath Send a change request, with nothing between them. The share sheet, the Muse-first note, and your saved Muse invite link all work exactly as before — only its spot in Settings changed."],"1.43.3":["New in Settings, right under About this app: Share Vault X. Paste your own Muse invite link once (find it in the Muse app, under the Invite button) and it is saved; the Share button then opens the share sheet with a ready-made invite that starts by telling your friend they need the Muse app first, includes your invite link so the sign-up is credited to you, and walks them through getting the install file from you and the quick first-open tour. No link saved yet? Share asks you to paste it first instead of sending an invite without it, and if there is no share sheet the message is copied instead","Bottom menu fix: going into Comics (or Lego) no longer adds an extra Comics tab to the bottom bar. The bar is now the same five tabs — Home, Search, Social, Portfolio, Settings — in the same order, in every section of the app"],"1.43.2":["Comics slabs rebuilt to look like real graded cases: the CGC label is now a slim band across the top of every slab — about a tenth of its height, the way a real holder runs — with all the same label information (grade 9.8, the signed line, WHITE Pages, cert number, credits) set in compact small print, and the cases themselves now wear the clear rigid acrylic look of the sealed cases: beveled edges, molded seams, and realistic light and reflections down the thick case walls. It applies everywhere the slab shows, including the Library comics binder pages"],"1.43.1":["Card alignment fixed in collection grids: the split buttons already lined up, and now the cards do too — every tile artwork starts at the exact same top height in its row (the taller tile no longer pushes its neighbours card down), with the buttons still pinned to their shared baseline","The Zelle mark is toned down as you asked: no more solid purple square — it is now an outlined line-art Z in the same neutral style as the cash icon beside it, everywhere it appears (the cash segment of the split button and the Pay the seller line on an order)"],"1.43.0":["Admin change notifications: when any Admin number changes — a new collector registers, item counts climb, ticket counts move — the Admin shield on Home gets a blue count badge on its upper right, like the mail marker. Inside the Admin page, every item that changed glows translucent blue until you tap that item to clear it; just opening the page clears nothing, and the Home badge clears when the last changed item is tapped","Library binder background fixed: opening a set binder now shows ALL of that set sealed products you own behind the binder — for Hyperia City that is the Booster Box, the Prerelease Box and the Booster Pack together — and their black studio backdrop is washed out, so only the acrylic-cased items float in the scene with no black rectangles","Floating scroll arrows faded further, just as you asked: they are still there on both edges, same size and behavior, but barely visible now — a faint ghost until you look for them"],"1.42.4":["The standalone Sealed tab is gone from the bottom menu — the bar now runs Home, Search, Social, Portfolio, Settings, and tab swipes follow that same order. No sealed items or data were removed","Set pages are reordered the way you asked: each set opens with its sealed products at the very top, then its cards, and the puzzle pieces and Full Puzzle Art now sit at the very, very bottom of the page"],"1.42.3":["Comics slabs: The Mandalorian #4 grade sits a little lower now, just as you asked, with nothing else on that slab changed","Aliens #1 and Batman #136: their gold Signature Series label bands are condensed further toward real slab proportions, with smaller type, grade box, barcode and hologram, and Aliens gets a stronger case bevel, seams and acrylic-style light streaks on its case walls","Slab turn view: comics now show real slab thickness as they turn — a thick molded clear edge and case back, so the slab reads as a rigid case turning in 3D instead of a flat card"],"1.42.2":["Library graded comics binder: each page now shows the rendered slab from the Comics section — the slab with the label band on top carrying the grade, title, cert and all label info over the real cover art — instead of the raw photo originally submitted for that comic. The binder open and flip animations are unchanged, and tapping a slab still opens its full page"],"1.42.1":["Library flip-through binders: pages now lay out 4 pockets across by 3 down — still 12 pockets per page, matching your physical Vault X binders. The cover open animation and finger-swipe page flipping are unchanged"],"1.42.0":["Hyperia City: the two Ink Drop counter cards are now in the binder — find both designs at the end of the set's Puzzle section, after the Full Puzzle Art, each with its real counter-card artwork. They start ghosted like any missing piece; tap one and use the count stepper to add the copies you own"],"1.41.4":["Library: the Lorcana shelf signs now wear the real Lorcana look — serif display lettering in gold, like the Disney Lorcana wordmark — and the Illumineer's Quest naming in the Library gets the same gold serif treatment, on the Quest shelf sign and on the Quest binder names (Deep Trouble, Palace Heist, The Great Hunny Rescue). Signs keep their size and place, and the promo artwork and icons are untouched"],"1.41.3":["Fixed: every Illumineer's Trove photo in Sealed had traces of its white studio backdrop baked into the picture — a white strip or halo around the box, and on Winterspell a white shadow puddle under it. All 14 Trove photos are cleaned down to the bare box, so the moment you mark one owned it shows as a clean cut-out in its acrylic case, exactly like the Quest boxes, with no white or ghostly border. Nothing else in Sealed changed"],"1.41.2":["Fixed: the Shimmering Skies and Ursula's Return chapter artwork now matches the rest of the Lorcana chapters — clean logo artwork on its own, like every other chapter tile, instead of the full banner pictures those two carried"],"1.41.1":["Fixed: the Admin shield badge on Home now appears right away, together with your Collector ID. It used to wait on the full app statistics loading from the server — the slowest check in the app — before it could show. The badge now uses the quick identity check, and the full statistics only load when you actually open Admin"],"1.41.0":["The graded comics get the flip-binder too: opening the Comics book in your Library lays the slab binder open on the table, one graded slab per page — flip through them and tap a slab to open its full page","Chapter tiles show their completion again, in order: set name, a progress bar with how many of the set you own, then the cost to complete below it","Chapter tile artwork gets a richer premium finish — a soft glow in each set's color and a gloss sweep — and the D23 and Illumineer's Quest tiles now present their art at the same clean size as the other tiles instead of blown up or cropped"],"1.40.0":["New: flip-through binders in the Library. Open any Lorcana binder spine and you are looking down at your own binder lying open on a table — the cover, carrying the set's artwork and name, swings open to pocket pages you flip through, with the page number and your pocket count at the top. Regular and foil sit side by side (regular first), owned cards in full color, missing cards ghosted with their real art, owned foils shimmering — and tap any card to open it. If you own that set's Illumineer's Trove or booster box, they stand on the table behind your binder too","Library: the shelves are families now — shelf one is the Lorcana chapter binders, chapters 1 through 14 under a Lorcana sign; every promo binder stands together on the next shelf under Lorcana Promos, with Promos as a playful sticker; the Quest binders get their own shelf under those","My Decks: every deck on display is now its own deck box, cartridge-style — its name embossed across the top, a tidy border around the front window, and one featured card showing in it. Pick the box's color and its featured card in the deck builder (until you pick, the window shows the deck's most valuable card). Tap a closed box and it opens — lid flips up, deck inside — then its page shows every card and how many copies","Admin: the Registered collectors tile is tappable now — tap it to open the list of every registered collector's username, with test accounts labeled","Profile: the little Library shelf is centered on the measured middle between your profile photo and the deck-box icon, and nudged down a touch — no change to its size, and the header spacing you approved is untouched"],"1.39.0":["Fixed: Update now actually updates. It used to bounce you back to Home still on the old version — the reload could be answered from the phone's saved copy. Now the update step fetches the new version and restarts onto it for real, and you will see an Updating note while it works","Fixed: refreshing on the Library page reloads the Library right where you are — it no longer throws you back to Home","Library: shelves are organized by universe now. All fourteen Lorcana chapters stand together on the first shelf, filled as full as it goes, and every shelf wears a little sign naming its universe — Lorcana, Comics, and any others as they arrive. Books slim down on a crowded shelf so everything fits","My Decks: the deck box photo is gone. Your deck box is now yours to create — pick its color, type in a custom name, and it is drawn right there on its shelf with your name on the front, like the chapters on the Library page","My Decks: your decks on display now stand as books on shelves below the deck box, Library-style — tap one to open its card list","Profile: the stretch between your name and badges and your bio is tightened up, so the whole header reads as one block — the Library shelf stays dropped under your Value and Collected stats, just with less empty air"],"1.38.0":["Profile: the little Library shelf of books now sits underneath your Value and Collected stats — centered under those two — and dropped down a few lines from where it sat before","New: value privacy. You can hide your total collection value from other collectors: use the switch in Settings under Sharing, or the little eye button right above the value figure on your own profile. Both places control the same setting and always agree, and you always see your own value","Home: the little eye button next to Your Collections opens its own window with the same collection switches as Settings — show or hide the Home tiles right there, without going to Settings","Owner only: an Admin shield badge now sits at the far left of Home's top row, on the same line as the mailbox icons. Nobody else ever sees it","Admin rebuilt: tapping the Home shield opens a brand-new Admin window (not Settings) with a rebuilt analytics-style dashboard — headline numbers up top, an items-by-kind ring chart, collector growth line and bar charts, tidy tables of collectors and most-owned items, trades and cash orders, tickets by status, and storage against the Supabase free plan. The same rebuilt dashboard now fills the Admin section in Settings too. Real server numbers only, with test profiles labeled"],"1.37.4":["Profile: the little Library shelf of books is now properly centered — the whole picture (the books, the shelf they stand on, and the Library label) is sized to the books and centered as one piece across the full space under your Value, Collected, and Trust Score stats, instead of sitting off to the left in part of that space. The deck-box icon stays at the right edge, and crowded shelves use slightly slimmer books so the picture stays clear of it"],"1.37.3":["Removed: the Dummy Friend test profile is deleted from the app entirely — its profile, its little collection, and its entry in Friends are gone, and it no longer figures in any Admin counts. Only you and Jarvis remain"],"1.37.2":["Fixed: the Great Hunny Rescue sealed photo is restored — the box standing in its clear acrylic display case on its black stand, the look that was approved, with no white or ghostly border around the photo","Profile: your @handle now sits right below your profile photo, and your bio sits one space below the handle","Profile: the little Library shelf picture nudged down and to the right a touch, so it sits centered in its space under your stats"],"1.37.1":["Profile: the deck-box icon moved all the way over to the right — it now sits at the edge of the profile, lined up with everything else on the page, instead of centered under the Trust Score"],"1.37.0":["Page changes glide even more smoothly now — switching tabs (by swipe or by tapping the menu) drifts in over a longer, softer motion instead of sliding quickly","The floating up and down scroll arrows are properly translucent now — a thin see-through frost, so the page ghosts through them as they float","Chapter icons cleaned up: the first three sets (The First Chapter, Rise of the Floodborn, Into the Inklands) got genuinely higher-resolution official logos, and every chapter tile's artwork now stretches to fill its tile edge to edge — no more pasted-photo look, no dead band at the bottom of the tile","Library: the binder info panel at the very bottom of the screen is gone. Tapping a spine now pops a small floating window in beside your tap — below it, or above it when that's what's clear, so your thumb never covers it — with the binder's name, chapter, and what you hold there","The little shelf of books on your profile is centered properly now","Profile: your handle (like @aruikis) moved down below your bio with more breathing room, centered under your profile photo","Sealed count picker: the phone's back button now closes the 1-through-9 picker without saving, just like tapping elsewhere does"],"1.36.0":["New: the Library. Your profile now carries a little shelf under your stats — thin binders in Vault X colors, one book for every chapter you own at least one card in (no book for a chapter you have none of). It fills the last empty spot in the profile header, on every profile — yours and your friends' alike","Tap the little shelf and your Library page opens: your whole shelf, one numbered spine per binder — every set, the promos, the Quests, and your graded comics — with the binders you have nothing in standing faded","In the Library, light-tap a spine to peek at whose binder it is and which chapter, and see how much of it you hold. Press and hold a spine (or tap Open this binder in the preview) to open that binder itself — from your own profile it takes you straight into that section of your binder"],"1.35.3":["Profiles condensed: the huge empty stretches on profile pages are gone. The deck-box icon now sits right under the Trust Score inside the photo's own row, so the @handle follows directly under the photo instead of a whole empty row later — on every profile","Your name and your achievement flags now sit together on the TOP line of your profile, up with the back button — not down at the lower right of your photo anymore. That goes for every profile: yours, your friends', Jarvis's, everyone's","Fixed: the Great Hunny Rescue sealed photo no longer carries a white border. The photo is now just the box itself, cropped clean, sitting in the same acrylic case as the other Quest boxes — the case look you approved is unchanged"],"1.35.2":["Fixed: Search now takes over the whole screen. Swiping or tapping from Home to Search used to leave Home visible behind and around the search field — Search is now its own full page on a solid background, and Home does not show through anywhere","Smoother page changes: moving between tabs — by swipe or by tapping the bottom menu — now glides in over about half a second with a soft slide and crossfade, instead of the quick sharp cut from before. Coming back from Search fades in gently the same way"],"1.35.1":["Swiping between tabs is animated now: the tab you swipe to slides in from the direction you swiped, with a quick crossfade as the old tab leaves — smooth and fast, no instant cut. It works through the whole bottom menu in both directions: swipe left for the next tab, right for the one before"],"1.35.0":["New: swipe between tabs. On the main screens, swipe left or right anywhere on the page to move to the next tab in the bottom menu's order — Home, Search, Sealed, Social, Portfolio, Settings — so from Home one swipe left lands you on Search without reaching down for the menu. Swiping right from Search closes it back to the screen underneath. It only fires on a clear sideways swipe, so normal scrolling up and down works exactly as before, and it stays out of the way while a card, window, or the scanner is open","Fixed: the count dial on the Sealed shelf now shows the full 1 through 9. The shelf tiles are narrow and were cutting the dial off at 4 — it now opens as a full-width panel floating above the tile, so every number is reachable, same as on card pages","Count dial: if you open it by accident, tapping anywhere else on the screen now closes it without changing the count — and that tap does nothing else, it just closes the dial. Works everywhere the dial appears: Sealed shelf, card pages, sealed and comic pages"],"1.34.1":["Fixed: the sideways count dial now opens ABOVE the + button instead of below it — holding the button no longer covers the dial with your thumb. That goes everywhere the dial appears: card finishes, the Copies owned bar on card, sealed, and comic pages, and the Sealed shelf tiles","Settings: every section heading now carries its quick-jump symbol right beside it — the swatch next to Theme, the shield next to Admin, and so on — so the icons at the top and the sections they jump to read as the same thing"],"1.34.0":["Mail fixed: tapping a message in your Inbox now opens that message on its own page — Subject and who it's from up top, the order with its invoice, and its message thread with the reply box — and the X at the top takes you back to the Inbox list. It no longer throws you into Social to find it","The Home mail icon now carries the same unread count as your Inbox, badge on the left of the envelope — no more arriving mail with no sign of it","New: delete messages from your Inbox. The trash on a message (in the list, or next to the X on the message itself) removes it from YOUR Inbox only, after one confirm tap — the purchase order or trade itself is not cancelled or changed, the other person keeps their copy, and if they message in that order again the item comes back with the new message","New: build your own decks. Open My Decks from your profile and tap Create a deck — name it, add cards from your own collection (up to the copies you own, at most 4 copies of any one card name, 60 cards to a deck), save it, and flip its On display switch to show it on your My Decks page where visitors can open its card list. Copies sitting in your decks count toward the decks hold-back in Trade availability","New: a Welcome page for new collectors. On first open it introduces Vault X with the ring artwork pulling into focus, a new user registers their username right there (checked against the network so no two collectors share a name) and gets their Collector ID, and then the tour walks them through the whole app step by step — no skipping — before Home. Established collectors see it once and can dismiss it; anyone can see it again from Settings, About this app","Count steppers: holding the + button now opens a sideways dial — 1 through 9 in a row — and tapping a number makes that the count, saved right away, no tapping nine times. It works on card pages, sealed pages, comics, and the Sealed shelf tiles too (the Illumineer's Quest Deep Trove long-hold that did nothing is fixed)","Home tiles: Settings gains a Your Collections section with a switch for each of the six tiles — turn off the ones you don't collect and they disappear from Home while the rest reflow, still centered three across. Display only: nothing is deleted, no totals change, and you can bring a tile back any time","The floating scroll arrows are translucent now — a quiet frost instead of solid buttons — and a set floats on BOTH edges of long pages, so either thumb can reach them","Cleaned up: the Illumineer's Quest: The Great Hunny Rescue photo now sits in the same clear acrylic display case as the rest of the Sealed shelf","Search: the heavy ghost pattern while the keyboard rises is fixed — opening the keyboard on the search field is one clean, stable motion, and it keeps the speed from the last fix"],"1.33.0":["New: your personal Inbox. The mail icon beside your name on Home opens it - every purchase order and trade offer involving you in one mail-style list, each with its Subject, who its From, the date, and a preview, unread ones marked. Opening one takes you straight to that order with its message thread open. Replies to your orders land here now, never silently inside Trades","Owners Inbox: your change-request tickets land in the Inbox too, titled by their type - Change Request, Bug, or Idea - with who sent them. Opening one opens that ticket. Tickets still work exactly as before in their own window","Opened orders now carry a mail-style header at the top: Subject: Purchase Order or Subject: Trade Offer, and From: the sender's name - above the invoice and the thread","Send a change request: the type pick is now just Bug or Idea - the generic Change Request type is gone","Fixed: the floating scroll arrows now actually appear on long pages - the Hyperia City set view, Settings, and everywhere else long. The first version measured the wrong thing and concluded no page was ever long, so they never showed","New: Puzzle sections in the binder. Open a set and scroll past its cards: the set's puzzle or lore insert cards are there as their own pockets - every piece numbered (like 2 of 4), ghosted when you don't have it, ownable with the usual steppers - plus a Full Puzzle Art item for the assembled picture. Rise of the Floodborn's Full Puzzle Art shows the completed Minnie Mouse puzzle photo","Puzzle counts, verified from listings and the Lorcana wiki: First Chapter 4, Rise of the Floodborn 4, Ursula's Return 9, Shimmering Skies 4, Azurite Sea 6, Archazia's Island 20 lore cards, Reign of Jafar 19 lore cards, Fabled 9, Whispers in the Well 18 lore cards, Winterspell 18 lore cards, Wilds Unknown 9, Hyperia City 9. Into the Inklands had rules cards instead of a puzzle, and Attack of the Vine! is not added yet - no verified piece count for it"],"1.32.0":["Zelle for cash purchases: save your Zelle handle once in Settings under Payment info. When you sell a card for cash, the buyer sees a Pay the seller line inside that purchase order - your handle with a Copy button - so they can pay you from their own bank app. It never appears on your profile", "The green cash side of the split button now pairs the cash icon with the Zelle mark, so the buy-outright side reads as cash / Zelle", "Order mail: when the other side replies inside one of your trade or purchase orders, you now get a mail indicator - beside your name on Home, on the Trades entry, and on the order itself with the number of new messages. Opening the thread clears it", "Purchase orders cleaned up to match the checkout invoice: who its with, the date, and the status up top, the card as an aligned line item, and a tidy totals block with the offer total next to the TCG suggested price", "Friend profiles tightened up: the stretch between the Friends / Trades / Marketplace / Forums bar and the Collection / Trade Match tabs is condensed - same content, less empty space", "Search smoothness: the page now rises in step with your keyboard instead of stuttering behind it"],"1.31.0":["New: a message with your order, right in the checkout - below the Send and Cancel buttons on the cash checkout there is now a Message with this order box. Write it before you send (need it tonight by 9? say so), hit Send purchase order, and the message travels with the order: the seller sees it right with the purchase and can answer in the same thread on that purchase. The trade checkout has the same box below its Send and Cancel buttons","Order messages follow the same rules as trade messages: text only, no photos, no links - and the red note stays at the bottom: Vault X does not send push notifications, so you only see new messages when you open the app","Search: the search window now sits low on the screen, about a quarter of the way up from the bottom, right in thumb reach - still centered side to side, and the keyboard still stays closed until you tap the field","Friend profiles: the name strip - their name, badge, and achievement flags - now sits directly underneath the Trades tab at the top of Social. The rest of the profile is unchanged, deck-box icon included","Home cleaned up: the note at the very bottom of Home - the one explaining the two pockets for every card number - now sits in a bordered window with a Hide button, like the other intro windows. The wording is unchanged","Portfolio cleaned up: everything under the Portfolio title - the As of line, your collection total, total paid, gain/loss, items, and averages - is now tidied into one bordered window with neat aligned rows instead of loose text. The tabs and charts below are unchanged"],"1.30.0":["Change requests are tickets now: sending one from Settings opens a ticket, and you can follow it right there under Your tickets - its status (Open, In Progress, or Completed) and who it is assigned to","The red envelope on Home is now just the envelope itself - no red circle or fill around it - sitting right next to your profile picture and name, with its count badge on the left side. Tapping it opens the ticket list in its own window, not the Settings page","Fixed: Cancel this purchase on the cash checkout now cancels everything - the whole cart clears, every chosen quantity goes back to zero, and the checkout bar is gone. Cancel this trade does the same for the trade cart","Fixed: the shield shortcut icon in Settings no longer flickers. It was the only jump icon that waited on data to exist, and its hold-on memory reset every time Settings closed, so it vanished until the slowest stats call returned and the row reshuffled. It now renders immediately like every other icon; the Admin section it points to stays owner-only","Portfolio: the Portfolio title now sits in a clean bordered window like the other section headers","Profiles: the collector name now sits on the same line as the deck-box icon, centered with it, instead of on its own line below the picture - and the deck-box icon border is toned down to a soft ring (the icon itself has not moved)"],"1.29.0":["The red envelope test, end to end: the TEST envelope sits on Home to the left of your name and photo, and tapping it takes you straight to your change-request inbox — the email-style inbox where requests list like emails with sender, kind, and date, unread ones bold with a red dot, and opening one reads like opening an email. A test message from Jarvis waits in the inbox; open it and tap Got it to finish the test","Search: the keyboard no longer pops up on its own when you open Search — it stays closed until you tap the search field yourself","Sealed: the intro (Your sealed Lorcana, kept mint in acrylic) now sits in a clean bordered window with a Hide button, like How trading works — hidden, it folds down to just the Sealed title with a Show button to bring it back, and your choice is remembered. The shelf and the Owned / All available switch are unchanged","Social: the intro under Social gets the same bordered hideable window, and the Friends area below it is now tidied inside its own border as well — same friends, same everything, just cleaner"],"1.28.1":["Fixed: the red envelope on Home now has a one-time test, just like the Update available note — it shows marked TEST even when no change request is waiting, so you can try it. Tap it and it takes you to your change-request inbox, where a test message from Jarvis waits: open it like an email and tap Got it to finish the test, and the test envelope is gone for good. Real change requests still bring the envelope back, with their real count"],"1.28.0":["Fixed for real this time: Mickey Mouse - Brave Little Tailor now shows its price in the cash checkout - $18.43 - and the TCG suggested total adds up (the three test cards total $21.53). The checkout was only reading prices the daily re-pricing had saved to the database, and that save never landed for this card; prices now fall back to the app's Lorcast price snapshot whenever the database has none, on the checkout, on a friend's profile, and in trade totals alike","New on the cash checkout: a red Cancel this purchase button sits next to Send purchase order - the red counterpart of that green. Tap it and you back out of the checkout; nothing is sent and no order is created","New on the trade checkout: the same red treatment - Cancel this trade next to Send proposal, backing you out without sending anything"],"1.27.0":["New in Sealed: the sealed catalog is complete — every gift set (7, including the Stitch Collector's Gift Set and the new Hyperia City Beast gift box), every starter deck (21 decks for sets 1 to 10, plus the 2-Player Starter Sets for Wilds Unknown and Hyperia City — Winterspell and Attack of the Vine! never released starter decks), and the Lorcana Gateway learn-to-play box. All priced from TCGplayer, all starting at Owned ×0, and the Type filter now includes Gift sets, Starter decks, and Gateway","Set pages: a set's sealed products now sit together at the very bottom of its page, after the last card — owned ones in full color, the rest ghosted like missing cards — and tapping one opens the sealed item to add your copy","Fixed: products you don't own yet on the Sealed shelf (All available) are now truly ghostly — the same washed-out, translucent treatment as missing binder cards. The display case's shine was covering the ghost effect before","The Sealed Type and Sort menus are redone in the app's own style — dark, rounded, blue-purple — instead of the phone's plain popup menu","New on item pages: hold the + button on a card finish or a sealed item and a scrollable counter opens — pick how many copies you have and it sets the count and saves automatically, no tapping one by one","New: ghost scroll arrows on long pages — a translucent down arrow floats at the right edge and rides to the bottom of the page, and an up arrow brings you back to the top. Settings has them too","Profile tidy-up: the decks entry under the Trust Score is now a line-drawn deck of cards inside a thick-bordered circle, drawn like the Settings icons and colored by your theme, centered under the Trust Score","Settings reshaped: About this app is the first section, the jump icons spread evenly across the full width, Send a change request sits near the top, and App updates moved to the very bottom of the page","About this app: the Vault X name and version line now sits at the very top of the section","Admin: the statistics are refined — bar charts for new collectors and new trades over the last 14 days, plus tiles for trades proposed, accepted, and completed, cash purchases, marketplace listings, and change requests waiting","Owner only: when change requests are waiting, a little red envelope appears on Home to the left of your name and picture — tap it to jump straight to the Admin inbox","Fixed: the Admin shortcut icon in Settings no longer flickers on and off","Change requests are now an email-style inbox for the owner: requests list like messages with sender, type, date, and a preview, unread ones bold with a red dot, and opening one shows it like an opened email and marks it read"],"1.26.0":["The update view is now final: it stands on its own as App updates — nothing but the update, its changelog, and two buttons at the very bottom, Update now and Update at a later time. No separate Finish step: picking either button completes the walkthrough, and backing out leaves it for next time. The one-time Test note on Home is armed again so you can retest this version","Fixed: refreshing the app now keeps you exactly where you are — a set view reopens on that set, an open card or sealed item reopens, your own profile page reopens, and a friend's profile reopens — instead of bouncing you back to a list or to Home","Checkout page cleaned up: it is now the Checkout heading and the checkout itself — the trades list and the small duplicate checkout label that sat under the big title are gone. The heading and its tagline sit in a window like How trading works, with a Hide button that folds it to its title row","Fixed: a cash checkout now shows only the cash invoice — the trade proposal panel no longer appears on a cash checkout by mistake, and the trade and cash flows stay separate","Fixed: a card with no tracked price no longer blocks a purchase order. The yellow note is information only now — you can still send, since your offer total covers the whole order — and you can remove that card right on the checkout and send the rest","The explanation paragraph at the top of Trades is removed — it repeated the How trading works window, which stays as the one explanation, the one you can hide","Home: the Collection value moved onto the same line as Your Collections, offset to the right, and the per-collection breakdown lines under the total are deleted — Home now shows just the label and the grand total","Fixed: going Back from My Decks now returns to the profile you came from, instead of landing on the Collector ID page. The My Decks entry on profiles is also smaller now: a round icon of your deck box, like an app icon, with no words on it, sitting under the Trust Score","Settings is rearranged most-used first — App updates and change requests, Theme, and Sharing up top, Trade Availability further down — and a centered row of small icons under the Settings heading jumps you straight to each section","Sealed shelf: new Owned and All available switch — Owned is your vault; All available shows the whole catalog, with the products you do not own yet faded like ghost cards so you can find and add them. There is also sorting by value, name, set, or date added, and a filter for Boxes, Packs, Quests, and Troves","New in Sealed: an Illumineer's Trove for every set — all fourteen, from The First Chapter through Hyperia City — each priced from TCGplayer and starting at Owned ×0 until you add your own"],"1.25.0":["Fixed: refreshing the app while you are standing on the checkout page now keeps you right there, cart intact, instead of throwing you back to the friend's profile","Fixed: Mickey Mouse - Brave Little Tailor now carries its real current TCGplayer price, so cash cart totals and the TCG suggested total add up for real — Jarvis's three test cards now total $21.53 together","Fixed: a purchase order offered at $0.00 — a gift between friends — now sends like any other amount","The Send purchase order button is now the brighter green, matching the checkout bar, so it stands out","Cash checkout is now laid out like a clean invoice: one line per card with its quantity, price each, and line total, then the TCG suggested total and your offer total set apart at the bottom","The trade checkout shows the same invoice-style totals for both sides, with the value difference between what you give and what you get","Trade availability now lives only in Settings — it no longer appears in Trades or on the checkout page","The How trading works section in Trades now has a Hide button: it collapses to its title row with a Show button, and your choice is remembered","Sharing in Settings is now one switch per connected friend, each on by default: when sharing is on, that friend can see your collection — turn it off per friend if you don't want them to","Tapping the Update available note on Home now opens the update view on its own instead of taking you to the Settings page: it shows the changelog with two choices, Update and Don't update at this time, and you can back out without deciding. The one-time Test note is armed again so you can run the corrected walkthrough","Deleted: the pockets-filled collection header is gone from everywhere in the app — binder, set pages, everywhere it still showed. If you want it back, just say so","New in Sealed: the first two Quest boxes are selectable catalog items too — Illumineer's Quest: Deep Trouble and Illumineer's Quest: Palace Heist, priced from TCGplayer, each starting at Owned ×0","Every Illumineer's Quest set page in the binder now shows its sealed box at the top — tap it to open the sealed item and set how many unopened boxes you own","New in Settings, right under App updates: Send a change request — pick Change request, Bug, or Idea, write your message, and it goes straight to the developer with your username and Collector ID on it","Your Vault X username now shows as ARuikis — capital A, capital R, then lowercase — on your Collector ID and profile"],"1.24.0":["New: messages inside trades — every trade and cash purchase in the Trades area now carries its own private message thread between the two collectors on that deal, for working out the swap and the meetup. There are no direct messages anywhere else in the app, no friends-list chat and no group chat","Trade messages are text only — no photos or attachments — and links are not allowed: a message with a link in it will not send until the link is removed. A thread closes to new messages when the deal ends, and the messages stay on the deal's record","At the bottom of every trade thread, in red: Vault X doesn't send push notifications — you'll only see new messages when you open the app","Trade Availability is now pick-and-mix: Keep one of each for the master set and Cards dedicated to my decks are two separate hold-backs you can switch on together, and both pools stay protected from trading. Everything I own and Nothing for now each stand alone","Social now reads Friends, Trades, Marketplace, Forums — Trades moved up next to Friends","The I want this split button is much slimmer now — same blue trade side and green cash side, squeezed down tight, then raised a touch (15 percent) from the tightest squeeze so it sits just right","New: the moment you add a card to a cart on a friend's profile, a bright green checkout bar appears above the bottom menu and stays while you keep browsing — it shows your carts and the cash running total. Its Checkout button opens a full checkout page of its own, and the green bar is gone while you are on it","Cash checkout now prices every card at its current-day TCGplayer value, and you can change the total before you send — the person receiving it sees your offered total right next to the TCG suggested market price, so they can check the offer before they accept","New: the app checks for updates on its own when you open it — when a newer version is live, a yellow Update available note appears on Home, to the left of your username. Tap it to read what changed and choose to update; nothing ever updates by itself. This version also carries a one-time test of that note, marked Test — tap it to walk through the whole update flow the way another collector would, and it goes away once you finish","Cash offers can be $0 — give a friend the cards as a gift. They still see the TCG suggested market price right next to the $0, so they know the value being handed over before they accept","Sharing moved into Settings and is on by default: connected friends can see your collection unless you turn sharing off in Settings, under Sharing","Scan a card: if a scan matches the wrong card — or no card at all — the results screen now carries a search: type the name, or the name and its number, pick the right printing, and add it from there. Matching is stricter too: when the collector number is readable, only that exact printing can match"],"1.23.0":["New in Sealed: Illumineer's Quest: The Great Hunny Rescue is now a selectable catalog item — find it on the Sealed shelf, open it for its price chart and Best Offer, and tap the plus stepper to add your own sealed copy. It is priced from TCGplayer and starts at Owned ×0, so nothing is added to your collection until you add it yourself","Cleaned up: the pockets-filled collection header at the top of the Sealed section is deleted — Sealed now opens straight into the sealed shelf. The Binder view keeps its header"],"1.22.0":["New: carts for trades and cash — on a friend's cards, the blue side of the split button adds the card to your trade cart and the green cash side adds it to your cash cart, one tap per card as you browse their collection. A cart bar on their profile keeps count, and checkout waits for you in the Trades area","The split button now only shows on cards the owner has copies of available to part with — when none are available, there is no button at all","Trade checkout has a Fill my order button: it builds your side automatically from cards you own that the other collector does not have, balanced by value so your side totals the same or less — and you can review and change any of it before you send","Cash checkout totals your cart at current market value as a pre-estimate before you send; sending puts one purchase request per card under Cash purchases for the owner to accept or decline, and you still settle the payment with them directly — no payment happens in the app"],"1.21.0":["New: the I want this button on a friend's cards is now split — the blue two-thirds still starts a card trade, and the green third with the cash symbol on it starts a cash purchase of that same card, right there","Cash purchases follow the app's usual deal flow: the request goes to the owner at their asking price when they have one, or the card's current market value — you see the price and pick how many copies before anything is sent — then the owner accepts or declines, you both confirm once it is done in person, and each side leaves the required thumbs up or down that feeds Trust Scores","Cash buying is a request arranged between collectors — you settle the payment with the seller directly, and no payment happens inside Vault X","Your cash purchases live in Social, in the Trades area, under Cash purchases"],"1.20.4":["Fixed: Reload to update in Settings now actually lands the new version — it refreshes the saved copy of the app first and then reloads, so an update can no longer spin back to the version you were already running","Moved: the Coming soon on the Home Marketplace entry is now an oval yellow pill on the same line as the word Marketplace, translucent and toned down, and the description line underneath is plain again","Restyled: the I want this button on a friend's cards — richer color with depth and a soft glow, so it looks properly pressable instead of plain"],"1.20.3":["Moved: on the Home Marketplace entry, Coming soon no longer sits over the word Marketplace itself — it now sits over the words and comics at the end of Buy and sell cards, sealed products, and comics, still translucent and toned down so it is visible without shouting"],"1.20.2":["Toned down: the Coming soon on the Home Marketplace entry is no longer a solid bright yellow pill — the words now sit right over the Marketplace label, exactly as tall as that label, in a translucent softer yellow that is easy to see without shouting"],"1.20.1":["The decks page now fronts the one deck box picture picked from the custom deck-case photos: a high-resolution wooden deck box with a patterned magnetic top, credited to its Etsy listing under the image. The color choices work on it exactly the same way"],"1.20.0":["My Decks on profiles: a pressable My Decks button now sits on your profile and on a friend's profile, next to Trade Match and achievements, and it opens that collector's own decks page","One deck box fronts the decks page: a single photo of a real custom laser-engraved wooden Lorcana deck box (credited to its Etsy seller under the image), instead of a row of different boxes","Deck box color is yours to change: Natural wood, Walnut, Midnight, Royal blue, Crimson, Emerald, or Violet tints the box photo and saves on this device — and each deck can wear its own color once decks are built","No decks are on display yet, and the page says so plainly rather than showing invented decks. Deck building and display stay in the workshop queue with the Binder and Deck copy-allocation design"],"1.19.0":["Held back: the Marketplace is not open yet — it needs more thought before collectors can buy and sell in it. Its doorway stays on Home and its tab stays in Social, with a big yellow Coming soon running diagonally across the area, and buying and selling are switched off until it opens","Held back: Forums get the same treatment — the boards stay right where they are under a translucent yellow Coming soon, visible but not clickable, while the section is refined","The Elsa and Stitch listing pictures are gone from the Marketplace area while it is held","New: Trades is fully working — Trade Match with a friend, propose a trade with real cards from each side, accept or decline, both sides confirm in person, and the required thumbs up or down afterwards, which feeds Trust Scores","New: tap I want this on a card in a friend's collection and it opens a new trade in the Trades area with that card ready — pick how many copies and what to give for it, then send","New: Trade availability in Settings and in Trades — choose how many copies of a card you are willing to part with. Keep one of each holds one copy back for your master sets; what you can trade is separate from what you own"],"1.18.1":["Cleaned up: the Vault X ring and name at the very top of Home are gone — the app already shows its name right above the page, so that band was saying it twice and leaving a tall empty space. Home now opens straight into your Collector ID and alerts","Cleaned up: the same duplicate ring and name in the middle of the profile header is gone too — the top of a profile is now just the back button and the menu, floating clean over the page","Updated: the back button and the three-dots menu on profile pages got a modern, soft fabric-like look — light frosted-glass circles instead of the heavy grey discs, with the three dots running across instead of down. They tap exactly like before, just easier on the eyes"],"1.18.0":["Updated: Where it lives now sits inside the Copies owned bar on every item page — the bar is split in half, with Where it lives on the left and Copies owned on the right, and the old section at the bottom of the page is gone","Tap Where it lives to open its menu: pick Binder, Deck box, Trade box, or Bulk box, pick a place you have used before, or create your own custom spot — custom spots are remembered and offered on your other items too","Each spot still keeps its own copy count, and the line under the bar shows how many of your copies are placed","New in Settings: Save collection count — leave it on for the Save button as always, or turn it off and every plus or minus tap on a card saves right away, no button needed"],"1.17.1":["Updated: Home now opens with the Vault X ring small and centered at the top, with Vault X right underneath it, in a tighter header with about a fifth less empty space at the top of the screen"],"1.17.0":["New: Where it lives — open any card, sealed product, or graded comic and you can record where the physical item sits: a binder with its page and pocket, a deck box, a trade box, or a bulk box with its row","Add as many spots as you need, each with its own copy count, so copies in different places are all accounted for — and edit or remove them any time"],"1.16.0":["New: an example price alert now sits on Home for anyone who has not set one yet — clearly labeled as an example, and tapping it explains how price alerts work","Tap Got it and the example is gone for good; your own alerts take its place the moment you set one"],"1.15.0":["New: your whole collection now backs up to the Vault X cloud server on its own — every card, sealed product, and graded comic, updated whenever your collection changes","New: if you ever start fresh on a new phone, your collection restores from that cloud backup when you sign back in","Settings: Your data and backups now shows your live backup status, with a Back up now button","Admin: a new Storage panel shows your Supabase plan limits with bars for how much database and file storage is used"],"1.14.0":["New in Settings: Your data and backups — plainly explains that your collection is stored in the cloud with your account, not just on your phone","New: export your whole collection from Settings — every card, sealed product, and graded comic — as an Excel spreadsheet, a CSV file, or JSON, to keep as your own backup","Updated: your profile header now carries the Vault X ring in the middle with Vault X under it in a tighter band, and the back and menu buttons got a cleaner, modern look"],"1.13.0":["Updated: graded comic slabs now look like your real CGC holders — the 9.8 sits big in a white box on the left, the CGC banner runs across the top, and the label carries your real credits, cert number over a barcode, and the holographic sticker on the right","The slab top stays tight like a real holder, and the cover now sits inset inside the case under the label, the way the actual slabs look"],"1.12.4":["Fixed: the Save the icon artwork button in Settings — it now works every time you tap it, sends the full-size artwork to your phone, and tells you where it went. You can also tap the artwork to see it full-size and save it from there"],"1.12.3":["New: your custom Vault X ring artwork is now in the app — find it at the top of Settings, in About this app, with a button to save a full-size copy"],"1.12.2":["Fixed: the pockets-filled collection header is now fully deleted from Settings and Portfolio — it no longer sits hidden at the top of those pages. Settings starts with its own sections and Portfolio opens with its title"],"1.12.1":["Fixed: the Japanese First Chapter pack now wears the same graded-slab look as every other sealed item — the whole Sealed shelf finally matches, pack by pack"],"1.12.0":["New: profile banners — tap the menu on your profile to add a banner photo. It sits behind your profile picture, which always stays whole and fully visible on top","Banners are optional: profiles without one look just like before, and you can change or remove yours anytime"],"1.11.4":["Fixed: the holographic shimmer on foil cards was too cloudy — the white haze is gone and the art stays crisp and clear under the rainbow shine, on every foil in the binder and the big card view","Fixed: the bottom menu now keeps the Search tab lit the whole time you are in Search — closing the keyboard no longer makes it jump back to Home"],"1.11.3":["Updated: every sealed item now wears the same approved graded-slab look — the Winterspell and Into the Inklands packs were the last two in the old display case, and they now match the Wilds Unknown and Hyperia City slab style exactly"],"1.11.2":["Fixed: the banner on profile pages is gone — it was cutting profile pictures in half. Your photo now sits whole at the top of your profile","New: tap the QR code on a profile and it opens big and scannable — on your own profile it opens the same full Collector ID page as the button on Home"],"1.11.1":["Fixed: the bottom menu no longer blurs under Search — it stays sharp and tappable above the blur, so you can tap any tab to leave Search","Fixed: graded comic slabs now use real-life proportions — the label at the top is a slim band like on an actual CGC holder, about 15 percent of the slab"],"1.11.0":["New: the Marketplace — find it in Social or from the Home page. Browse listings from other collectors, with the asking price next to a Buy Now button and a note showing how the price compares to market value","Sell anything from your own collection — cards, sealed products like a booster box, and graded comics — and manage your listings any time","Buy Now claims an item and notifies the seller (no payment in the app yet — you arrange the deal and meet in person). You can also make an offer instead","Sales complete only when both sides confirm, and then each side must leave a thumbs up or down — ratings stay hidden until both are in, and finished deals feed Trust Scores"],"1.10.0":["New profile pages, styled after Shiny: banner, photo, stats, and your whole collection in a searchable grid — for you and for friends","Achievements are here — earn badge icons next to your name from real collection milestones, like your first 100 items or a finished master set","Trade Match on a friend's profile: one tap shows the cards they have that you need, and the cards you have that they need","The plus and minus buttons now have much bigger touch areas, so they're easy to hit with a thumb","The app gives a light tap back when you make a selection — haptics, with an on/off switch in Settings"],"1.9.0":["New Admin page in Settings, just for the app owner: live stats from the server — how many collectors, how many items logged, the most-owned cards, and more","Aliens #1 now shows as the full graded slab in its case, gold label on top with the real label details","Took the KEY badges off the comic covers","Settings and Portfolio no longer show the pockets-filled header at the top","Portfolio now starts with its own title at the top, like Settings and Social"],"1.8.1":["Fixed the Hyperia City booster box photo — it now shows the real booster display box, sealed in its case","Most sealed packs now sit in a clean clear slab — like a graded holder, but with no label at the top","Fresh official box art for the three Illumineer's Quest sets","The set tiles in the binder are a little taller"],"1.8.0":["New in Settings: a Theme picker — Vault Dark, Light, Midnight Purple, Crimson Ember, and High Contrast","Tap a theme and it applies everywhere right away, even the highlighted tab in the bottom menu","Your theme choice saves to your profile, so it stays picked"],"1.7.0":["A new vault door app icon — the old book icon is gone","The highlighted tab in the bottom menu now glows blue-violet to match the app, instead of green"],"1.6.0":["The app has a new name: Vault X — same collection, same everything, new name and a new vault icon","Fixed the Owned count on sealed tiles so the words and the plus and minus buttons sit on one straight line"],"1.5.1":["Fixed the First Chapter pack mix-up — the English pack and the Japanese pack are two separate items again, each with its own photo","The Hyperia City booster box now shows closed and sealed, and the acrylic cases on sealed items look thicker and clearer","On the home page, Collection Distribution now shows the percentage first, and the extra three-dots button is gone","The Owned count and its plus and minus buttons now line up neatly on item pages","Added a note by the Re-price now button: prices refresh on their own once a day"],"1.5.0":["Set pictures in the Lorcana binder are bigger and much sharper","Every item now floats and turns on its page — cards, sealed products, and graded comics. Drag to turn it yourself","Update checks now tell you exactly what changed, right here in Settings"],"1.4.0":["Your username and Collector ID now save to the server, so friends can find you","The Friends list reads from the server too — the Jarvis test user really lives there now","Fixed the missing price graph on Fru Fru - VIP Guest and other card pages","The Best Offer button now shows the TCGplayer logo","New button on a friend's page: Cards They Have That I Need, with its own search and set filter","Removed the extra Binders button from the bottom menu — tap a collection to open its binder"]}`;
export const CHANGELOG: Record<string, string[]> = JSON.parse(
  CHANGELOG_EMBED.slice("mc-changelog:".length),
);
